#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: what the owner does on Cloudflare once, so answer subdomains can be served
# (issue #141, docs/adr/0019-hosted-pages-are-served-by-a-worker-of-their-own.md).
#
# Run it from the repository root after a deploy that includes the Pages Worker:
#   scripts/hosted-pages-setup.sh
# It needs the 1Password CLI signed in to the Nearcited vault for the last stage, which sets the
# main Worker's secret. Nothing is written to a file.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=8

ZONE_ID="6fe7a0d57c6ac9c92fa89a00c06690a3"
DASH="https://dash.cloudflare.com/?to=/:account/nearcited.com"

banner "Hosted pages: Cloudflare setup"

stage "Before you start"
say "Hosted pages are served by a second Worker, nearcited-pages. Its route is made in this"
say "setup, so it must be deployed first: by the Deploy workflow from a main that has it."
if ! confirm "Has a deploy with the Pages Worker run (nearcited-pages is listed under Workers & Pages)?"; then
  warn "Run the Deploy workflow first, then start this again."
  exit 1
fi

stage "The fallback origin record"
say "Every answer subdomain is sent to one name on nearcited.com. It needs a DNS record that"
say "points nowhere, because the Pages Worker answers before any origin would."
open_url "$DASH/dns/records"
step "Add record → Type: AAAA"
step "Name: pages-origin    IPv6 address: 100::"
step "Proxy status: Proxied (orange cloud) → Save"
pause "Press Enter once the record is saved"

stage "Turn on custom hostnames"
say "This is Cloudflare for SaaS. Cloudflare lists the first 100 custom hostnames as included on"
say "every plan, then 10 cents each a month. It may ask you to add a payment method first."
open_url "$DASH/ssl-tls/custom-hostnames"
step "Enable Cloudflare for SaaS if it offers to, and follow its prompts."
step "Fallback Origin: pages-origin.nearcited.com → Add Fallback Origin"
step "Wait until the fallback origin's status says Active (a minute or two; refresh the page)."
pause "Press Enter once it says Active"

stage "The name owners point their record at"
say "Each answer subdomain's record points at its own name under pages.nearcited.com. One"
say "wildcard record makes every one of those names reach the fallback origin."
open_url "$DASH/dns/records"
step "Add record → Type: CNAME"
step "Name: *.pages    Target: pages-origin.nearcited.com"
step "Proxy status: Proxied (orange cloud) → Save"
pause "Press Enter once the record is saved"

stage "Keep the app off the Pages Worker"
say "A route runs before the app's own domain, so this one, with no Worker, goes first: it keeps"
say "nearcited.com going straight to the app once the next stage adds the catch-all route."
open_url "$DASH/workers"
step "Workers Routes → Add route"
step "Route: nearcited.com/*    Worker: None → Save"
pause "Press Enter once the route is saved"

stage "Send answer subdomains to the Pages Worker"
open_url "$DASH/workers"
step "Workers Routes → Add route"
step "Route: */*    Worker: nearcited-pages → Save"
step "Check the list: nearcited.com/* (None) and */* (nearcited-pages), and nothing else new."
pause "Press Enter once both routes are listed"
if curl -fsS -o /dev/null "https://nearcited.com/" ; then
  printf '  %s✓%s nearcited.com still answers\n' "$GREEN" "$RESET"
else
  warn "nearcited.com did not answer. Delete the */* route and check the nearcited.com/* one."
  pause "Press Enter to carry on"
fi

stage "A token for custom hostnames, and nothing else"
say "The main Worker registers each answer subdomain as a custom hostname, and removes it, with"
say "this token. Give it one permission on one zone."
open_url "https://dash.cloudflare.com/profile/api-tokens"
step "Create Token → Create Custom Token (Get started)"
step "Token name: Nearcited hosted pages"
step "Permissions: Zone → SSL and Certificates → Edit"
step "Zone Resources: Include → Specific zone → nearcited.com"
step "Continue to summary → Create Token → copy the token (it is shown once)"
ask_secret HOSTNAMES_TOKEN "Paste the token:"
# Cloudflare refuses a page of fewer than five hostnames, so ask for five.
answer=$(curl -sS -H "Authorization: Bearer $HOSTNAMES_TOKEN" \
  "https://api.cloudflare.com/client/v4/zones/$ZONE_ID/custom_hostnames?per_page=5" || true)
if [[ "$answer" == *'"success":true'* ]]; then
  printf '  %s✓%s the token can read the zone'"'"'s custom hostnames\n' "$GREEN" "$RESET"
else
  warn "The token could not read the zone's custom hostnames. Check its permission and zone."
  # Cloudflare's own words, which never include the token.
  grep -o '"message":"[^"]*"' <<<"$answer" | sed 's/^/    /' || true
  exit 1
fi
step "Keep it in 1Password too: Nearcited vault → item Cloudflare → add a password field"
step "named hostnames_token, and paste the token there."
pause "Press Enter once it is in 1Password"

stage "Give the token to the main Worker"
say "This sets CLOUDFLARE_HOSTNAMES_TOKEN on the deployed Worker, using the deploy credentials in"
say "1Password. Hosted pages are offered to owners from the moment it is set."
if confirm "Set the secret on the nearcited Worker now?"; then
  printf '%s' "$HOSTNAMES_TOKEN" | \
    CLOUDFLARE_API_TOKEN="op://Nearcited/Cloudflare/api_token" \
    CLOUDFLARE_ACCOUNT_ID="op://Nearcited/Cloudflare/account_id" \
    op run -- npx -y pnpm@10.28.0 --filter @nearcited/api exec \
      wrangler secret put CLOUDFLARE_HOSTNAMES_TOKEN >/dev/null
  WRITTEN_SECRET+=("CLOUDFLARE_HOSTNAMES_TOKEN (Worker secret)")
  printf '  %s✓ set%s CLOUDFLARE_HOSTNAMES_TOKEN on the nearcited Worker\n' "$GREEN" "$RESET"
else
  SKIPPED+=("Worker secret CLOUDFLARE_HOSTNAMES_TOKEN: pnpm --filter @nearcited/api exec wrangler secret put CLOUDFLARE_HOSTNAMES_TOKEN")
fi

finish
